/**
 * Statistical language model runtime.
 *
 * The raw tables (generated by `tooling/build-language-model.ts`) weigh ~75 kB,
 * so they are loaded lazily through a dynamic import: tools that never need
 * them never pay for them, and the bundler emits them as a separate chunk.
 */
import { printableRatio } from '../util/bytes';

export interface EnglishModel {
  /** log10 P(next letter | previous letter), letters as 0–25. */
  bigram(prev: number, next: number): number;
  /** log10 P(letter begins a word). */
  initial(letter: number): number;
  /** log10 P(letter ends a word). */
  final(letter: number): number;
  /** log10 P(quadgram), lower-case a–z only. */
  quadgram(q: string): number;
  /** log10 P(word) estimated from its frequency rank (Zipf's law), or null if unknown. */
  word(word: string): number | null;
  /** True if the word is part of the vocabulary. */
  has(word: string): boolean;
  /** 1-based frequency rank of a word (1 = "the"), or null if unknown. */
  rank(word: string): number | null;
}

let cached: Promise<EnglishModel> | null = null;

/** Loads (once) and returns the English model. */
export function loadEnglishModel(): Promise<EnglishModel> {
  cached ??= import('./data/english-model').then((data) => {
    const quads = new Map<string, number>();
    for (let i = 0; i < data.QUADGRAM_SCORES.length; i++) {
      quads.set(data.QUADGRAM_KEYS.slice(i * 4, i * 4 + 4), -data.QUADGRAM_SCORES[i]! / 100);
    }
    const quadFloor = -data.QUADGRAM_FLOOR / 100;
    const ranks = new Map<string, number>();
    data.VOCABULARY.split(' ').forEach((w, i) => ranks.set(w, i + 1));
    const bigram = data.BIGRAM.map((v) => -v / 100);
    const initial = data.WORD_INITIAL.map((v) => -v / 100);
    const final = data.WORD_FINAL.map((v) => -v / 100);
    const unigram = data.UNIGRAM.map((p) => Math.log10(p));
    // Quadgrams outside the top-3000 table back off to a first-order Markov estimate
    // (unigram × three bigram transitions), discounted so table entries always win.
    const backoff = (q: string) => {
      const [a, b, c, d] = [...q].map((ch) => ch.charCodeAt(0) - 97) as [
        number,
        number,
        number,
        number,
      ];
      const estimate =
        unigram[a]! + bigram[a * 26 + b]! + bigram[b * 26 + c]! + bigram[c * 26 + d]!;
      return Math.max(quadFloor, estimate - 0.35);
    };
    return {
      bigram: (a, b) => bigram[a * 26 + b]!,
      initial: (a) => initial[a]!,
      final: (a) => final[a]!,
      quadgram: (q) => quads.get(q) ?? backoff(q),
      // Zipf: p(rank) ≈ 0.08 / rank for English.
      word: (w) => {
        const rank = ranks.get(w);
        return rank === undefined ? null : Math.log10(0.08 / rank);
      },
      has: (w) => ranks.has(w),
      rank: (w) => ranks.get(w) ?? null,
    };
  });
  return cached;
}

/**
 * Mean quadgram log-probability of the letters in `text`.
 * English prose scores between about −3.7 and −5; shuffled or enciphered
 * letters score below −7.
 */
export function quadgramFitness(model: EnglishModel, text: string): number {
  const letters = text.toLowerCase().replace(/[^a-z]/g, '');
  if (letters.length < 4) return -7.5;
  let sum = 0;
  for (let i = 0; i + 4 <= letters.length; i++) sum += model.quadgram(letters.slice(i, i + 4));
  return sum / (letters.length - 3);
}

/** Maps quadgram fitness from [−7.5, −4] (gibberish … fluent English) onto [0, 1]. */
export function normalizedFitness(fitness: number): number {
  return Math.min(1, Math.max(0, (fitness + 7.5) / 3.5));
}

/** Share of word tokens found in the vocabulary. */
export function wordCoverage(model: EnglishModel, text: string): number {
  const words = text.toLowerCase().match(/[a-z]+(?:'[a-z]+)?/g);
  if (!words?.length) return 0;
  let hits = 0;
  for (const w of words) if (model.has(w)) hits++;
  return hits / words.length;
}

const PERSIAN_COMMON = new Set(
  'و در به از که این را با است آن برای یک خود تا کرد بر هم نیز شد می شده ما من تو او ها های شود دارد باشد یا اما اگر هر چه بود ای سلام دنیا ایران'.split(
    ' ',
  ),
);

/**
 * A single 0–1 plausibility score: "does this look like natural language?"
 * Combines printability, English quadgram fitness and dictionary coverage,
 * with a Persian branch so decoded Farsi text is recognised as well.
 */
export function languageScore(model: EnglishModel, text: string): number {
  const sample = text.slice(0, 4000);
  if (!sample.trim()) return 0;
  const printable = printableRatio(sample);
  if (printable < 0.6) return printable * 0.1;

  const arabicScript = (sample.match(/[\u0600-\u06FF]/g) ?? []).length;
  const latin = (sample.match(/[A-Za-z]/g) ?? []).length;
  if (arabicScript > latin) {
    const words = sample.split(/[\s\u200C.,،؛!?؟]+/).filter(Boolean);
    const common = words.filter((w) => PERSIAN_COMMON.has(w)).length;
    const shape = arabicScript / Math.max(1, sample.replace(/\s/g, '').length);
    return Math.min(
      1,
      printable * (0.55 * shape + 0.45 * Math.min(1, (common / words.length) * 3)),
    );
  }

  if (latin < 3) return 0.05 * printable;
  const letterShare = latin / sample.replace(/\s/g, '').length;
  const fit = normalizedFitness(quadgramFitness(model, sample));
  const coverage = wordCoverage(model, sample);
  const spaced = /\s/.test(sample.trim()) ? 1 : 0.85;
  return Math.min(
    1,
    printable ** 2 * Math.min(1, letterShare * 1.25) * spaced * (0.55 * fit + 0.45 * coverage),
  );
}
